-- This release's defaults: the settings of the Creator's preset (Data\PresetCreator.lua), written over the addon's own
-- (BattlefieldInfo.lua DEFAULTS) before your saved settings are read, so they
-- only fill in what you haven't set. Lists (button orders...) are taken whole.
-- Generated by tools\release_defaults.lua; regenerate rather than edit.

local _, ns = ...

local function IsList(t)
	local n = #t
	if n == 0 then return false end
	for k in pairs(t) do
		if type(k) ~= "number" or k < 1 or k > n or k % 1 ~= 0 then return false end
	end
	return true
end

local function Over(dst, src)
	for k, v in pairs(src) do
		if type(v) == "table" and type(dst[k]) == "table" and not IsList(v) then
			Over(dst[k], v)
		else
			dst[k] = v
		end
	end
end

